const SLUG_MAP = {
 "engine": "engine-parts",
 "braking": "brake-parts",
 "cooling": "cooling-system",
 "filtration": "filters",
 "hydraulics": "hydraulic-parts",
 "transmission": "transmission-parts",
 "electrical": "electrical-parts",
 "steering": "steering-parts",
 "suspension": "suspension-chassis",
 "misc": "spare-parts",
 "cabin": "cab-body-parts",
 "drivetrain": "gearbox-differential",
 "bearings": "bearing-bushing"
};

const BRAND_SLUG_RE = /^\/([a-z-]+)\/([a-z]+)(\/.*)?$/;

export default {
  async fetch(request) {
    const url = new URL(request.url);

    // www -> apex
    if (url.hostname === "www.partstrading.com") {
      url.hostname = "partstrading.com";
      return Response.redirect(url.toString(), 301);
    }

    const path = url.pathname;

    // Exact legacy /pages/... mappings -> real destination page (452 entries)
    if (EXACT[path]) {
      return Response.redirect("https://partstrading.com" + EXACT[path], 301);
    }

    // /products/:id -> real destination page if we still have one (52,573 of
    // 52,695 deleted thin redirect pages recovered from git history), else homepage
    if (path.startsWith("/products/")) {
      const id = decodeURIComponent(path.slice("/products/".length).replace(/\.html$/i, ""));
      const dest = PRODUCTS_MAP[id];
      return Response.redirect("https://partstrading.com" + (dest || "/"), 301);
    }

    // Generic /pages/* catch-all for anything not in EXACT above
    if (path.startsWith("/pages/")) {
      return Response.redirect("https://partstrading.com/", 301);
    }

    // Brand-agnostic old category slug -> current slug, e.g. /cat/engine/X -> /cat/engine-parts/X
    const m = path.match(BRAND_SLUG_RE);
    if (m && SLUG_MAP[m[2]]) {
      const rest = m[3] || "";
      return Response.redirect("https://partstrading.com/" + m[1] + "/" + SLUG_MAP[m[2]] + rest, 301);
    }

    // Not a legacy URL — pass through to GitHub Pages origin untouched
    return fetch(request);
  }
};
